package it.cavallium.rockserver.core.common.distributed;

import java.io.*;
import java.util.*;

/** Receiver-local completion of a published configuration change, distinct from original range birth/ACTIVATE. */
public final class NativeTopologyRelocationCompletion {
    public static final int MAX_BYTES=TopologyChange.MAX_DEFINITION_BYTES+65536+512;
    private final TopologyChange.Definition definition;private final UUID catalogue;private final ApplyPosition publicationCut,position,configurationPosition;private final byte[] configuration,registrationDigest,encoded;private final ReplicaDescriptor receiver;
    public NativeTopologyRelocationCompletion(NativeTopologyLearnerRegistration registration,TopologyChange.Definition definition,UUID catalogue,ApplyPosition publicationCut,ApplyPosition position,ApplyPosition configurationPosition,byte[] configuration) {
        this.definition=Objects.requireNonNull(definition);this.catalogue=Objects.requireNonNull(catalogue);this.publicationCut=Objects.requireNonNull(publicationCut);this.position=Objects.requireNonNull(position);this.configurationPosition=Objects.requireNonNull(configurationPosition);this.configuration=configuration.clone();this.registrationDigest=registration.digest();
        var range=definition.targets().getFirst();receiver=range.replicas().stream().filter(replica->sameIdentity(replica,registration.receiver())).findFirst().orElseThrow(()->new IllegalArgumentException("Published relocation excludes receiver identity"));var original=registration.definition().targets().getFirst();
        if(definition.kind()!=TopologyChange.Kind.RELOCATE || !catalogue.equals(registration.catalogue()) || publicationCut.term()<1 || publicationCut.index()<1 || position.term()<1 || configurationPosition.term()<1 || configurationPosition.index()>position.index() || configurationPosition.term()>position.term() || configurationPosition.index()==position.index() && configurationPosition.term()!=position.term() || configuration.length<1 || configuration.length>65536 || !range.groupId().equals(original.groupId()) || !range.rangeId().equals(original.rangeId()) || range.rangeEpoch()!=original.rangeEpoch() || !Arrays.equals(range.lowerInclusive(),original.lowerInclusive()) || !Arrays.equals(range.upperExclusive(),original.upperExclusive()) || !definition.header().clusterId().equals(registration.schema().clusterId()) || !definition.header().databaseId().equals(registration.schema().databaseId()) || !definition.header().domainId().equals(registration.schema().domainId()))throw new IllegalArgumentException("Relocation completion changed qualified receiver/cut/geometry");encoded=encodeCurrent();
    }
    private NativeTopologyRelocationCompletion(TopologyChange.Definition definition,UUID catalogue,ApplyPosition publicationCut,ApplyPosition position,ApplyPosition configurationPosition,byte[] configuration,byte[] registrationDigest,ReplicaDescriptor receiver) {this.definition=definition;this.catalogue=catalogue;this.publicationCut=publicationCut;this.position=position;this.configurationPosition=configurationPosition;this.configuration=configuration;this.registrationDigest=registrationDigest;this.receiver=receiver;encoded=encodeCurrent();}
    public TopologyChange.Definition definition(){return definition;}public UUID catalogue(){return catalogue;}public ApplyPosition publicationCut(){return publicationCut;}public ApplyPosition position(){return position;}public ApplyPosition configurationPosition(){return configurationPosition;}public ReplicaDescriptor receiver(){return receiver;}public byte[] configuration(){return configuration.clone();}public byte[] registrationDigest(){return registrationDigest.clone();}public byte[] encode(){return encoded.clone();}public boolean writable(){return receiver.role()==ReplicaDescriptor.Role.VOTER;}
    public void requireRegistration(NativeTopologyLearnerRegistration registration){var expected=new NativeTopologyRelocationCompletion(registration,definition,catalogue,publicationCut,position,configurationPosition,configuration);if(!Arrays.equals(encoded,expected.encoded))throw new IllegalArgumentException("Relocation completion changed original registration");}
    public void requireRequest(TopologyChange.Definition definition,byte[] configuration,UUID catalogue,ApplyPosition publicationCut){if(!Arrays.equals(this.definition.encode(),definition.encode()) || !Arrays.equals(this.configuration,configuration) || !this.catalogue.equals(catalogue) || !this.publicationCut.equals(publicationCut))throw new IllegalArgumentException("Relocation completion retry changed common publication");}
    public void requireCut(ApplyPosition cut){if(cut==null || position.index()>cut.index() || position.term()>cut.term() || position.index()==cut.index() && position.term()!=cut.term())throw new IllegalArgumentException("Relocation completion exceeds native prefix");}
    private static boolean sameIdentity(ReplicaDescriptor first,ReplicaDescriptor second){return first.nodeId().equals(second.nodeId()) && first.nodeIncarnation().equals(second.nodeIncarnation()) && first.replicaId().equals(second.replicaId()) && first.peerId().equals(second.peerId()) && first.address().equals(second.address());}
    private byte[] encodeCurrent(){try{var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeInt(0x4e545243);byte[] definitionBytes=definition.encode();out.writeInt(definitionBytes.length);out.write(definitionBytes);for(UUID id:List.of(catalogue,receiver.nodeId(),receiver.nodeIncarnation(),receiver.replicaId())){out.writeLong(id.getMostSignificantBits());out.writeLong(id.getLeastSignificantBits());}for(var cut:List.of(publicationCut,position,configurationPosition)){out.writeLong(cut.term());out.writeLong(cut.index());}out.write(registrationDigest);out.writeUTF(receiver.peerId());out.writeUTF(receiver.address());out.writeByte(receiver.role().ordinal());out.writeInt(configuration.length);out.write(configuration);return bytes.toByteArray();}catch(IOException impossible){throw new AssertionError(impossible);}}
    public static NativeTopologyRelocationCompletion decode(byte[] bytes){if(bytes==null || bytes.length<4 || bytes.length>MAX_BYTES)throw new IllegalArgumentException("Invalid relocation completion size");try{var in=new DataInputStream(new ByteArrayInputStream(bytes));if(in.readInt()!=0x4e545243)throw new IllegalArgumentException("Invalid completion tag");int size=in.readInt();if(size<1 || size>TopologyChange.MAX_DEFINITION_BYTES || size>in.available())throw new IllegalArgumentException("Invalid completion definition");var definition=TopologyChange.Definition.decode(in.readNBytes(size));var catalogue=uuid(in);var node=uuid(in);var incarnation=uuid(in);var replica=uuid(in);var publication=new ApplyPosition(in.readLong(),in.readLong());var position=new ApplyPosition(in.readLong(),in.readLong());var configPosition=new ApplyPosition(in.readLong(),in.readLong());byte[] digest=in.readNBytes(32);String peer=in.readUTF(),address=in.readUTF();int role=in.readUnsignedByte();if(role>=ReplicaDescriptor.Role.values().length)throw new IllegalArgumentException("Invalid completion role");var receiver=new ReplicaDescriptor(node,incarnation,replica,peer,address,ReplicaDescriptor.Role.values()[role]);size=in.readInt();if(size<1 || size>65536 || size!=in.available() || digest.length!=32 || definition.kind()!=TopologyChange.Kind.RELOCATE || publication.term()<1 || publication.index()<1 || position.term()<1 || configPosition.term()<1 || configPosition.index()>position.index() || configPosition.term()>position.term() || configPosition.index()==position.index() && configPosition.term()!=position.term() || definition.targets().getFirst().replicas().stream().noneMatch(receiver::equals))throw new IllegalArgumentException("Invalid completion identity/cuts");var result=new NativeTopologyRelocationCompletion(definition,catalogue,publication,position,configPosition,in.readNBytes(size),digest,receiver);if(!Arrays.equals(bytes,result.encoded))throw new IllegalArgumentException("Noncanonical completion");return result;}catch(IOException invalid){throw new IllegalArgumentException("Invalid completion encoding",invalid);}}
    private static UUID uuid(DataInputStream in)throws IOException{return new UUID(in.readLong(),in.readLong());}
    @Override public boolean equals(Object other){return other instanceof NativeTopologyRelocationCompletion completion && Arrays.equals(encoded,completion.encoded);}@Override public int hashCode(){return Arrays.hashCode(encoded);}
}
